/// <summary>
/// Will create attributelink's respective lookup
/// </summary>
/// <param name = "_formStringControl">The control which will open the lookup</param>
/// <param name = "_link">the attribute link record to be used to open the lookup</param>
public static void doLookUp(FormStringControl _formStringControl, GUPPricingAttributeLink _link)
{
    if (_link.pricingAttribute().isRefRecIdValue())
    {
        _link.pricingAttribute().lookupAllowedValues(_formStringControl as Object);
    }
    else if (_link.AttributeName)
    {
        _link.lookupAllowedValues(_formStringControl);
    }
}

/// <summary>
/// Display correct attribute values, when refId is stored as _priceAttributeValue.
/// </summary>
/// <param name = "_priceAttributeName">the price attribute name</param>
/// <param name = "_priceAttributeValue">the price attribute value</param>
/// <param name = "_link">the attribute link record to be used get the actual string values from priceAttributesValue of RecID type</param>
/// <returns>String with the value</returns>
 public static str getPriceAttributeValue(str _priceAttributeName, str _priceAttributeValue, GUPPricingAttributeLink _link)
 {
     if (!_link || _priceAttributeValue == "")
     {
         return _priceAttributeValue;
     }

     if (_link.pricingAttribute().isRefRecIdValue())
         return _link.pricingAttribute().getRefValue(_priceAttributeValue);
     else
         return _priceAttributeValue;

 }
